        "- 夏季里农事忙，要到田间（采蚕桑）、（插秧）。\r\n  - \"早起勤耕作，归来（戴月光）\"写出农民早出晚归的辛劳。\r\n  - 表现丰收喜悦的句子是\"，\"。（答案：谷像黄金粒粒香/身体虽辛苦，心里喜洋洋）"
