        "句式/修辞",
        "- 大量运用排比、对偶，气势磅礴，富有节奏感。\r\n- 用\"红日、伏流、潜龙、乳虎、鹰隼、奇花、干将\"等生机勃勃的事物，比喻（象征）少年中国的光明未来。"
