    "title": "落花生",
    "kind": "现代文（第2课）",
    "category": "text-recitation",
    "position": "",
    "requirement": "重点段落（需以学校课本为准）",
    "optional": true,
    "author": "许地山",
    "dynasty": "",
    "text": "许地山\n\n父亲说：\"花生的好处很多，有一样最可贵：它的果实埋在地里，不像桃子、石榴、苹果那样，把鲜红嫩绿的果实高高地挂在枝头上，使人一见就生爱慕之心。你们看它矮矮地长在地上，等到成熟了，也不能立刻分辨出来它有没有果实，必须挖起来才知道。\"\n\n我们都说是，母亲也点点头。\n\n父亲接下去说：\"所以你们要像花生，它虽然不好看，可是很有用。\"\n\n我说：\"那么，人要做有用的人，不要做只讲体面，而对别人没有好处的人。\"\n\n父亲说：\"对。这是我对你们的希望。\"",
    "notes": [
      [
        "爱慕之心",
        "喜爱、羡慕的心情。"
      ],
      [
        "分辨",
        "区分、辨别（不要写成\"分辩\"，\"分辩\"是辩解之意）。"
      ],
      [
        "体面",
        "这里指外表好看、有派头。"
      ],
      [
        "有用",
        "指对别人、对社会有实际贡献。"
      ],
      [
        "主旨情感",
        "全文借物喻人，通过一家人议论花生的好处，说明做人要做有用的人，不要做只讲体面而对别人没有好处的人，表现了作者不慕虚名、求实务实的人生追求。"
      ],
      [
        "表现手法",
        "借物喻人、对比（花生与桃子、石榴、苹果对比）。"
      ],
      [
        "默写易错字",
        "- \"慕\"不要写成\"幕\"\"墓\"。\r\n- \"分辨\"不要写成\"分辩\"。\r\n- \"矮\"不要写成\"诶\"。"
      ],
      [
        "常考理解填空",
        "1. 文中花生最可贵的品质是：。（果实埋在地里，不炫耀，默默奉献）\r\n2. 点明全文中心、揭示做人道理的句子是：，________。（人要做有用的人，不要做只讲体面，而对别人没有好处的人）\r\n3. 父亲用桃子、石榴、苹果与花生作对比，是为了突出花生________的特点。（外表不好看但很有用/默默奉献）"
      ]
    ]
