    "optional": false,
    "author": "郑燮",
    "dynasty": "",
    "text": "咬定青山不放松，立根原在破岩中。\n千磨万击还坚劲，任尔东西南北风。",
    "notes": [
      [
        "咬定",
        "紧紧扎根在土里，像咬住一样。"
      ],
      [
        "立根",
        "扎根。\r\n- 原：本来。"
      ],
      [
        "破岩",
        "破裂的岩石缝隙。"
      ],
      [
        "千磨万击",
        "经历无数的磨难和打击。\r\n- 坚劲（jìng）：坚韧挺拔。\r\n- 任：任凭。\r\n- 尔：你。"
      ],
      [
        "译文",
        "竹子紧紧咬住青山毫不放松，把根深深地扎在破裂的岩石之中。经历千万种磨难和打击依然坚韧挺拔，任凭你东西南北风怎么吹刮。"
      ],
      [
        "主旨情感",
        "这是一首题画诗，也是托物言志诗。赞美了竹子坚韧不拔、刚正不阿的品格，表达了诗人面对挫折不屈服、坚守气节的人生态度。"
      ],
      [
        "默写易错字",
        "\"劲\"读 jìng，是力字旁，不要写成\"颈\"；\"尔\"不要写成\"你\"。"
      ],
      [
        "常考理解填空",
        "\"，\"表现了竹子坚韧不屈的品格。（千磨万击还坚劲，任尔东西南北风）"
      ]
    ]
